            users[i].getPrivilegeList().add(pathPrivilege);
            users[i].getRoleList().add("role" + j);
        }
    }
    // save
    for (User user : users) {
        try {
            accessor.saveUser(user);
        } catch (IOException e) {
            fail(e.getMessage());
        }
    }
    // load
    for (User user : users) {
        try {
            User loadedUser = accessor.loadUser(user.getName());
