@Test
public void simpleTest() throws IOException, QueryProcessException, MetadataException {
    IMemTable memTable = new PrimitiveMemTable();
    int count = 10;
    String deviceId = "d1";
    String[] measurementId = new String[count];
    for (int i = 0; i < measurementId.length; i++) {
        measurementId[i] = "s" + i;
    }
    int dataSize = 10000;
    for (int i = 0; i < dataSize; i++) {
        memTable.write(deviceId, new MeasurementSchema(measurementId[0], TSDataType.INT32, TSEncoding.PLAIN), dataSize - i - 1, i + 10);
    }
    for (int i = 0; i < dataSize; i++) {
        memTable.write(deviceId, new MeasurementSchema(measurementId[0], TSDataType.INT32, TSEncoding.PLAIN), i, i);
    }
    ReadOnlyMemChunk memChunk = memTable.query(deviceId, measurementId[0], new MeasurementSchema(measurementId[0], TSDataType.INT32, TSEncoding.RLE, CompressionType.UNCOMPRESSED, Collections.emptyMap()), Long.MIN_VALUE, null);
    IPointReader iterator = memChunk.getPointReader();
    for (int i = 0; i < dataSize; i++) {
        iterator.hasNextTimeValuePair();
        TimeValuePair timeValuePair = iterator.nextTimeValuePair();
        Assert.assertEquals(i, timeValuePair.getTimestamp());
        Assert.assertEquals(i, timeValuePair.getValue().getValue());
    }
}

