@Test
public void testTimedFlushMemTable() throws IllegalPathException, InterruptedException, WriteProcessException, TriggerExecutionException {
    // create one seq memtable & close
    TSRecord record = new TSRecord(10000, deviceId);
    record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(1000)));
    processor.insert(new InsertRowPlan(record));
    Assert.assertEquals(1, MemTableManager.getInstance().getCurrentMemtableNumber());
    processor.syncCloseAllWorkingTsFileProcessors();
    Assert.assertEquals(0, MemTableManager.getInstance().getCurrentMemtableNumber());
    // create one unseq memtable
    record = new TSRecord(1, deviceId);
    record.addTuple(DataPoint.getDataPoint(TSDataType.INT32, measurementId, String.valueOf(1000)));
    processor.insert(new InsertRowPlan(record));
    Assert.assertEquals(1, MemTableManager.getInstance().getCurrentMemtableNumber());
    // check memtable's flush interval & flush the unsequence memtable
    long preFLushInterval = config.getUnseqMemtableFlushInterval();
    config.setUnseqMemtableFlushInterval(5);
    Thread.sleep(500);
    processor.timedFlushMemTable();
    // wait until memtable flush task is done
    Assert.assertEquals(1, processor.getWorkUnsequenceTsFileProcessors().size());
    TsFileProcessor tsFileProcessor = processor.getWorkUnsequenceTsFileProcessors().iterator().next();
    FlushManager flushManager = FlushManager.getInstance();
    int waitCnt = 0;
    while (tsFileProcessor.getFlushingMemTableSize() != 0 || tsFileProcessor.isManagedByFlushManager() || flushManager.getNumberOfPendingTasks() != 0 || flushManager.getNumberOfPendingSubTasks() != 0 || flushManager.getNumberOfWorkingTasks() != 0 || flushManager.getNumberOfWorkingSubTasks() != 0) {
        Thread.sleep(500);
        ++waitCnt;
        if (waitCnt % 10 == 0) {
            logger.info("already wait {} s", waitCnt / 2);
        }
    }
    Assert.assertEquals(0, MemTableManager.getInstance().getCurrentMemtableNumber());
    config.setUnseqMemtableFlushInterval(preFLushInterval);
}

@Test
public void testWriteAndFlush() throws IOException, WriteProcessException, MetadataException {
    logger.info("testWriteAndFlush begin..");
    processor = new TsFileProcessor(storageGroup, SystemFileFactory.INSTANCE.getFile(filePath), sgInfo, this::closeTsFileProcessor, (tsFileProcessor) -> true, true);
    TsFileProcessorInfo tsFileProcessorInfo = new TsFileProcessorInfo(sgInfo);
    processor.setTsFileProcessorInfo(tsFileProcessorInfo);
    this.sgInfo.initTsFileProcessorInfo(processor);
    SystemInfo.getInstance().reportStorageGroupStatus(sgInfo, processor);
    List<TsFileResource> tsfileResourcesForQuery = new ArrayList<>();
    processor.query(deviceId, measurementId, new MeasurementSchema(measurementId, dataType, encoding, CompressionType.UNCOMPRESSED, props), context, tsfileResourcesForQuery);
    assertTrue(tsfileResourcesForQuery.isEmpty());
    for (int i = 1; i <= 100; i++) {
        TSRecord record = new TSRecord(i, deviceId);
        record.addTuple(DataPoint.getDataPoint(dataType, measurementId, String.valueOf(i)));
        processor.insert(new InsertRowPlan(record));
    }
    // query data in memory
    tsfileResourcesForQuery.clear();
    processor.query(deviceId, measurementId, new MeasurementSchema(measurementId, dataType, encoding, CompressionType.UNCOMPRESSED, props), context, tsfileResourcesForQuery);
    assertFalse(tsfileResourcesForQuery.get(0).getReadOnlyMemChunk().isEmpty());
    List<ReadOnlyMemChunk> memChunks = tsfileResourcesForQuery.get(0).getReadOnlyMemChunk();
    for (ReadOnlyMemChunk chunk : memChunks) {
        IPointReader iterator = chunk.getPointReader();
        for (int num = 1; num <= 100; num++) {
            iterator.hasNextTimeValuePair();
            TimeValuePair timeValuePair = iterator.nextTimeValuePair();
            assertEquals(num, timeValuePair.getTimestamp());
            assertEquals(num, timeValuePair.getValue().getInt());
        }
    }
    // flush synchronously
    processor.syncFlush();
    tsfileResourcesForQuery.clear();
    processor.query(deviceId, measurementId, new MeasurementSchema(measurementId, dataType, encoding, CompressionType.UNCOMPRESSED, props), context, tsfileResourcesForQuery);
    assertTrue(tsfileResourcesForQuery.get(0).getReadOnlyMemChunk().isEmpty());
    assertEquals(1, tsfileResourcesForQuery.get(0).getChunkMetadataList().size());
    assertEquals(measurementId, tsfileResourcesForQuery.get(0).getChunkMetadataList().get(0).getMeasurementUid());
    assertEquals(dataType, tsfileResourcesForQuery.get(0).getChunkMetadataList().get(0).getDataType());
    processor.syncClose();
}

