        for (int i = 0; i < 10; i++) {
            statement.execute(String.format("INSERT INTO root.sg.device%s(timestamp,s) VALUES(2,2)", i));
            statement.execute(String.format("SELECT device%s.s into device%s.t from root.sg;", i, i));
        }
