        }
        statement.execute("delete from root.sg1.d0.s0 where time <= 15");
        long count = 0;
        try (ResultSet resultSet = statement.executeQuery("select * from root")) {
            while (resultSet.next()) {
                count++;
            }
        }
        System.out.println(count);
    }
}

