    String metadata = String.format("load \"%s\"", filePath);
    Planner processor = new Planner();
    OperateFilePlan plan = (OperateFilePlan) processor.parseSQLToPhysicalPlan(metadata);
    assertEquals(String.format("OperateFilePlan{file=%s, targetDir=null, autoCreateSchema=true, sgLevel=1, verify=true, " + "operatorType=LOAD_FILES}", filePath), plan.toString());
    metadata = String.format("load \"%s\" autoregister=true", filePath);
    processor = new Planner();
    plan = (OperateFilePlan) processor.parseSQLToPhysicalPlan(metadata);
    assertEquals(String.format("OperateFilePlan{file=%s, targetDir=null, autoCreateSchema=true, sgLevel=1, verify=true, " + "operatorType=LOAD_FILES}", filePath), plan.toString());
    metadata = String.format("load \"%s\" autoregister=false", filePath);
    processor = new Planner();
    plan = (OperateFilePlan) processor.parseSQLToPhysicalPlan(metadata);
    assertEquals(String.format("OperateFilePlan{file=%s, targetDir=null, autoCreateSchema=false, sgLevel=1, verify=true, " + "operatorType=LOAD_FILES}", filePath), plan.toString());
    metadata = String.format("load \"%s\" autoregister=true,sglevel=3", filePath);
    processor = new Planner();
    plan = (OperateFilePlan) processor.parseSQLToPhysicalPlan(metadata);
    assertEquals(String.format("OperateFilePlan{file=%s, targetDir=null, autoCreateSchema=true, sgLevel=3, verify=true, " + "operatorType=LOAD_FILES}", filePath), plan.toString());
    metadata = String.format("load \"%s\" autoregister=true,sglevel=3,verify=false", filePath);
    processor = new Planner();
    plan = (OperateFilePlan) processor.parseSQLToPhysicalPlan(metadata);
    assertEquals(String.format("OperateFilePlan{file=%s, targetDir=null, autoCreateSchema=true, sgLevel=3, verify=false, " + "operatorType=LOAD_FILES}", filePath), plan.toString());
    metadata = String.format("load \"%s\" autoregister=true,sglevel=3,verify=true", filePath);
    processor = new Planner();
    plan = (OperateFilePlan) processor.parseSQLToPhysicalPlan(metadata);
    assertEquals(String.format("OperateFilePlan{file=%s, targetDir=null, autoCreateSchema=true, sgLevel=3, verify=true, " + "operatorType=LOAD_FILES}", filePath), plan.toString());
}

