@Test
public void aggregateTest() {
    try {
        PartialPath path = new PartialPath(SERIES_READER_TEST_SG + ".device0.sensor0");
        Set<String> allSensors = new HashSet<>();
        allSensors.add("sensor0");
        QueryDataSource queryDataSource = new QueryDataSource(seqResources, unseqResources);
        SeriesAggregateReader seriesReader = new SeriesAggregateReader(path, allSensors, TSDataType.INT32, new QueryContext(), queryDataSource, null, null, null, true);
        AggregateResult aggregateResult = AggregateResultFactory.getAggrResultByName("count", TSDataType.INT32, true);
        int loopTime = 0;
        while (seriesReader.hasNextFile()) {
            if (seriesReader.canUseCurrentFileStatistics()) {
                Statistics fileStatistics = seriesReader.currentFileStatistics();
                aggregateResult.updateResultFromStatistics(fileStatistics);
                seriesReader.skipCurrentFile();
                continue;
            }
            while (seriesReader.hasNextChunk()) {
                if (seriesReader.canUseCurrentChunkStatistics()) {
                    Statistics chunkStatistics = seriesReader.currentChunkStatistics();
                    aggregateResult.updateResultFromStatistics(chunkStatistics);
                    seriesReader.skipCurrentChunk();
                    continue;
                }
                while (seriesReader.hasNextPage()) {
                    if (seriesReader.canUseCurrentPageStatistics()) {
                        Statistics pageStatistic = seriesReader.currentPageStatistics();
                        aggregateResult.updateResultFromStatistics(pageStatistic);
                        seriesReader.skipCurrentPage();
                        continue;
                    }
                    if (loopTime >= 0 && loopTime < 13) {
                        assertEquals((long) loopTime * 20, aggregateResult.getResult());
                    } else if (loopTime >= 13 && loopTime < 17) {
                        assertEquals((long) loopTime * 20 + 40, aggregateResult.getResult());
                    } else if (loopTime >= 17) {
                        assertEquals((long) loopTime * 20 + 60, aggregateResult.getResult());
                    }
                    while (seriesReader.hasNextPage()) {
                        BatchData nextOverlappedPageData = seriesReader.nextPage();
                        aggregateResult.updateResultFromPageData(nextOverlappedPageData);
                        nextOverlappedPageData.resetBatchData();
                        assertTrue(nextOverlappedPageData.hasCurrent());
                    }
                    loopTime++;
                }
            }
        }
        assertEquals(500L, aggregateResult.getResult());
    } catch (IOException | QueryProcessException | IllegalPathException e) {
        e.printStackTrace();
        fail();
    }
}

@Test
public void test() throws IOException, IllegalPathException {
    QueryDataSource dataSource = new QueryDataSource(seqResources, unseqResources);
    Set<String> allSensors = new HashSet<>();
    allSensors.add("sensor0");
    SeriesReaderByTimestamp seriesReader = new SeriesReaderByTimestamp(new PartialPath(SERIES_READER_TEST_SG + ".device0.sensor0"), allSensors, TSDataType.INT32, new QueryContext(), dataSource, null, true);
    long[] timestamps = new long[500];
    for (int i = 0; i < 500; i++) {
        timestamps[i] = i;
    }
    Object[] values = seriesReader.getValuesInTimestamps(timestamps, timestamps.length);
    for (int time = 0; time < 500; time++) {
        if (time < 200) {
            Assert.assertEquals(time + 20000, values[time]);
        } else if (time < 260 || (time >= 300 && time < 380) || (time >= 400)) {
            Assert.assertEquals(time + 10000, values[time]);
        } else {
            Assert.assertEquals(time, values[time]);
        }
    }
}

@Test
public void batchTest() {
    try {
        Set<String> allSensors = new HashSet<>();
        allSensors.add("sensor0");
        SeriesReader seriesReader = new SeriesReader(new PartialPath(SERIES_READER_TEST_SG + ".device0.sensor0"), allSensors, TSDataType.INT32, new QueryContext(), seqResources, unseqResources, null, null, true);
        IBatchReader batchReader = new SeriesRawDataBatchReader(seriesReader);
        int count = 0;
        while (batchReader.hasNextBatch()) {
            BatchData batchData = batchReader.nextBatch();
            assertEquals(TSDataType.INT32, batchData.getDataType());
            assertEquals(20, batchData.length());
            for (int i = 0; i < batchData.length(); i++) {
                long expectedTime = i + 20 * count;
                assertEquals(expectedTime, batchData.currentTime());
                if (expectedTime < 200) {
                    assertEquals(20000 + expectedTime, batchData.getInt());
                } else if (expectedTime < 260 || (expectedTime >= 300 && expectedTime < 380) || expectedTime >= 400) {
                    assertEquals(10000 + expectedTime, batchData.getInt());
                } else {
                    assertEquals(expectedTime, batchData.getInt());
                }
                batchData.next();
            }
            count++;
        }
    } catch (IOException | IllegalPathException e) {
        e.printStackTrace();
        fail();
    }
}

