@Test
public void onEventUsingSingleSensorHandler() throws Exception {
    LocalIoTDBHandler localIoTDBHandler = new LocalIoTDBHandler();
    localIoTDBHandler.open(new LocalIoTDBConfiguration("root.sg1.d1", new String[] { "s1" }, new TSDataType[] { TSDataType.INT32 }));
    for (int i = 0; i < 10000; ++i) {
        localIoTDBHandler.onEvent(new LocalIoTDBEvent(i, i));
    }
    localIoTDBHandler.close();
    Class.forName(Config.JDBC_DRIVER_NAME);
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        Assert.assertTrue(statement.execute("select * from root"));
        try (ResultSet resultSet = statement.getResultSet()) {
            ResultSetMetaData resultSetMetaData = resultSet.getMetaData();
            checkHeader(resultSetMetaData, "Time,root.sg1.d1.s1,", new int[] { Types.TIMESTAMP, Types.INTEGER });
            int count = 0;
            while (resultSet.next()) {
                for (int i = 1; i <= resultSetMetaData.getColumnCount(); i++) {
                    assertEquals(count, Double.parseDouble(resultSet.getString(i)), 0.0);
                }
                count++;
            }
            Assert.assertEquals(10000, count);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void onEventUsingMultiSensorsHandler() throws Exception {
    LocalIoTDBHandler localIoTDBHandler = new LocalIoTDBHandler();
    localIoTDBHandler.open(new LocalIoTDBConfiguration("root.sg1.d1", new String[] { "s1", "s2", "s3", "s4", "s5", "s6" }, new TSDataType[] { TSDataType.INT32, TSDataType.INT64, TSDataType.FLOAT, TSDataType.DOUBLE, TSDataType.BOOLEAN, TSDataType.TEXT }));
    for (int i = 0; i < 10000; ++i) {
        localIoTDBHandler.onEvent(new LocalIoTDBEvent(i, i, (long) i, (float) i, (double) i, i % 2 == 0, Binary.valueOf(String.valueOf(i))));
    }
    localIoTDBHandler.close();
    Class.forName(Config.JDBC_DRIVER_NAME);
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        Assert.assertTrue(statement.execute("select * from root"));
        try (ResultSet resultSet = statement.getResultSet()) {
            ResultSetMetaData resultSetMetaData = resultSet.getMetaData();
            checkHeader(resultSetMetaData, "Time,root.sg1.d1.s1,root.sg1.d1.s2,root.sg1.d1.s3," + "root.sg1.d1.s4,root.sg1.d1.s5,root.sg1.d1.s6,", new int[] { Types.TIMESTAMP, Types.INTEGER, Types.BIGINT, Types.FLOAT, Types.DOUBLE, Types.BOOLEAN, Types.VARCHAR });
            int count = 0;
            while (resultSet.next()) {
                for (int i = 1; i <= resultSetMetaData.getColumnCount(); i++) {
                    try {
                        assertEquals(count, Double.parseDouble(resultSet.getString(i)), 0.0);
                    } catch (NumberFormatException e) {
                        assertEquals(count % 2 == 0, Boolean.parseBoolean(resultSet.getString(i)));
                    }
                }
                count++;
            }
            Assert.assertEquals(10000, count);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

