@Test
public void testSeqFile() throws InterruptedException {
    if (skip) {
        return;
    }
    final long[] maxLength = { 0 };
    ByteBuffer[] buffers = new ByteBuffer[2];
    buffers[0] = ByteBuffer.allocateDirect(IoTDBDescriptor.getInstance().getConfig().getWalBufferSize() / 2);
    buffers[1] = ByteBuffer.allocateDirect(IoTDBDescriptor.getInstance().getConfig().getWalBufferSize() / 2);
    Thread writeThread = new Thread(() -> {
        int cnt = 0;
        try {
            Class.forName(Config.JDBC_DRIVER_NAME);
        } catch (ClassNotFoundException e) {
            e.printStackTrace();
            return;
        }
        try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
            Statement statement = connection.createStatement()) {
            // System.out.println("Exit after " + cnt + " insertion");
            while (!Thread.interrupted()) {
                String sql = String.format("INSERT INTO root.logFileTest.seq(timestamp,val) VALUES (%d, %d)", ++cnt, cnt);
                statement.execute(sql);
                WriteLogNode logNode = MultiFileLogNodeManager.getInstance().getNode("root.logFileTest.seq" + IoTDBConstant.SEQFILE_LOG_NODE_SUFFIX, () -> buffers);
                File bufferWriteWALFile = new File(logNode.getLogDirectory() + File.separator + ExclusiveWriteLogNode.WAL_FILE_NAME);
                if (bufferWriteWALFile.exists() && bufferWriteWALFile.length() > maxLength[0]) {
                    maxLength[0] = bufferWriteWALFile.length();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    });
    writeThread.start();
    Thread.sleep(runtime);
    writeThread.interrupt();
    while (writeThread.isAlive()) {
    }
    for (ByteBuffer byteBuffer : buffers) {
        MmapUtil.clean((MappedByteBuffer) byteBuffer);
    }
}

