            Statement statement = connection.createStatement()) {
            // System.out.println("Exit after " + cnt + " insertion");
            while (!Thread.interrupted()) {
                String sql = String.format("INSERT INTO root.logFileTest.unsequence(timestamp,val) VALUES (%d, %d)", ++cnt, cnt);
                statement.execute(sql);
                WriteLogNode logNode = MultiFileLogNodeManager.getInstance().getNode("root.logFileTest.unsequence" + IoTDBConstant.UNSEQFILE_LOG_NODE_SUFFIX, () -> buffers);
                File WALFile = new File(logNode.getLogDirectory() + File.separator + ExclusiveWriteLogNode.WAL_FILE_NAME);
                if (WALFile.exists() && WALFile.length() > maxLength[0]) {
                    maxLength[0] = WALFile.length();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    });
    writeThread.start();
    Thread.sleep(runtime);
    writeThread.interrupt();
    while (writeThread.isAlive()) {
    }
    for (ByteBuffer byteBuffer : buffers) {
        MmapUtil.clean((MappedByteBuffer) byteBuffer);
    }
}

