        node.write(new InsertRowPlan(new PartialPath("root.sg.device0"), 100, "sensor0", TSDataType.INT64, String.valueOf(0)));
        node.write(new InsertRowPlan(new PartialPath("root.sg.device0"), 2, "sensor1", TSDataType.INT64, String.valueOf(0)));
        for (int i = 1; i < 5; i++) {
            node.write(new InsertRowPlan(new PartialPath("root.sg.device" + i), i, "sensor" + i, TSDataType.INT64, String.valueOf(i)));
        }
        node.write(insertTablePlan());
        DeletePlan deletePlan = new DeletePlan(0, 200, new PartialPath("root.sg.device0.sensor0"));
        node.write(deletePlan);
        node.close();
        replayer.replayLogs(() -> {
            ByteBuffer[] byteBuffers = new ByteBuffer[2];
            byteBuffers[0] = ByteBuffer.allocateDirect(IoTDBDescriptor.getInstance().getConfig().getWalBufferSize() / 2);
            byteBuffers[1] = ByteBuffer.allocateDirect(IoTDBDescriptor.getInstance().getConfig().getWalBufferSize() / 2);
            return byteBuffers;
        });
        for (int i = 0; i < 5; i++) {
            ReadOnlyMemChunk memChunk = memTable.query("root.sg.device" + i, "sensor" + i, new MeasurementSchema("sensor" + i, TSDataType.INT64, TSEncoding.RLE, CompressionType.UNCOMPRESSED, Collections.emptyMap()), Long.MIN_VALUE, null);
            IPointReader iterator = memChunk.getPointReader();
            if (i == 0) {
                assertFalse(iterator.hasNextTimeValuePair());
            } else {
                assertTrue(iterator.hasNextTimeValuePair());
                TimeValuePair timeValuePair = iterator.nextTimeValuePair();
                assertEquals(i, timeValuePair.getTimestamp());
                assertEquals(i, timeValuePair.getValue().getLong());
                assertFalse(iterator.hasNextTimeValuePair());
            }
        }
        Modification[] mods = modFile.getModifications().toArray(new Modification[0]);
        assertEquals(1, mods.length);
        assertEquals("root.sg.device0.sensor0", mods[0].getPathString());
        assertEquals(0, mods[0].getFileOffset());
        assertEquals(200, ((Deletion) mods[0]).getEndTime());
        assertEquals(2, tsFileResource.getStartTime("root.sg.device0"));
        assertEquals(100, tsFileResource.getEndTime("root.sg.device0"));
        for (int i = 1; i < 5; i++) {
            assertEquals(i, tsFileResource.getStartTime("root.sg.device" + i));
            assertEquals(i, tsFileResource.getEndTime("root.sg.device" + i));
        }
        // test insert tablet
        for (int i = 0; i < 2; i++) {
            ReadOnlyMemChunk memChunk = memTable.query("root.sg.device5", "sensor" + i, new MeasurementSchema("sensor" + i, TSDataType.INT64, TSEncoding.PLAIN, CompressionType.UNCOMPRESSED, Collections.emptyMap()), Long.MIN_VALUE, null);
            // s0 has datatype boolean, but required INT64, will return null
            if (i == 0) {
                assertNull(memChunk);
            } else {
                IPointReader iterator = memChunk.getPointReader();
                iterator.hasNextTimeValuePair();
                for (int time = 0; time < 100; time++) {
                    TimeValuePair timeValuePair = iterator.nextTimeValuePair();
                    assertEquals(time, timeValuePair.getTimestamp());
                    assertEquals(time, timeValuePair.getValue().getLong());
                }
            }
        }
    } finally {
        modFile.close();
        MultiFileLogNodeManager.getInstance().deleteNode(logNodePrefix + tsFile.getName(), (ByteBuffer[] byteBuffers) -> {
            for (ByteBuffer byteBuffer : byteBuffers) {
                MmapUtil.clean((MappedByteBuffer) byteBuffer);
            }
        });
        modF.delete();
        tsFile.delete();
        tsFile.getParentFile().delete();
    }
}

