@Test
public void multiCasesTest() throws SQLException {
    String[] timeSeriesArray = { "root.sg1.aa.bb", "root.sg1.aa.bb.cc", "root.sg1.aa" };
    for (String timeSeries : timeSeriesArray) {
        try {
            writeStatement.execute(String.format("create timeseries %s with datatype=INT64, encoding=PLAIN, compression=SNAPPY", timeSeries));
        } catch (Exception e) {
            if (timeSeries.equals("root.sg1.aa.bb")) {
                e.printStackTrace();
                fail();
            }
        }
    }
    ResultSet resultSet = null;
    // try to read data on each node.
    for (Statement readStatement : readStatements) {
        resultSet = readStatement.executeQuery("show timeseries");
        Set<String> result = new HashSet<>();
        while (resultSet.next()) {
            result.add(resultSet.getString(1));
        }
        Assert.assertEquals(1, result.size());
        Assert.assertTrue(result.contains("root.sg1.aa.bb"));
        Assert.assertFalse(result.contains("root.sg1.aa.bb.cc"));
        Assert.assertFalse(result.contains("root.sg1.aa"));
        resultSet.close();
    }
    // test https://issues.apache.org/jira/browse/IOTDB-1331
    writeStatement.execute("create timeseries root.ln.wf01.wt01.temperature WITH DATATYPE=FLOAT, ENCODING=RLE");
    String[] initDataArray = { "INSERT INTO root.ln.wf01.wt01(timestamp,temperature) values(200,20.71)", "INSERT INTO root.ln.wf01.wt01(timestamp,temperature) values(220,50.71)" };
    for (String initData : initDataArray) {
        writeStatement.execute(initData);
    }
    // try to read data on each node.
    for (Statement readStatement : readStatements) {
        resultSet = readStatement.executeQuery("select avg(temperature) from root.ln.wf01.wt01");
        if (resultSet.next()) {
            Assert.assertEquals(35.71, resultSet.getDouble(1), 0.01);
        } else {
            fail("expect 1 result, but get an empty resultSet.");
        }
        Assert.assertFalse(resultSet.next());
        resultSet.close();
    }
    // test https://issues.apache.org/jira/browse/IOTDB-1348
    initDataArray = new String[] { "INSERT INTO root.ln.wf01.wt01(timestamp, temperature) values(250, 10.0)", "INSERT INTO root.ln.wf01.wt01(timestamp, temperature) values(300, 20.0)", "INSERT INTO root.ln.wf01.wt01(timestamp, temperature) values(350, 25.0)" };
    for (String initData : initDataArray) {
        writeStatement.execute(initData);
    }
    // try to read data on each node.
    for (Statement readStatement : readStatements) {
        resultSet = readStatement.executeQuery("select last * from root.ln.wf01.wt01;");
        Assert.assertTrue(resultSet.next());
        double last = Double.parseDouble(resultSet.getString(3));
        Assert.assertEquals(25.0, last, 0.1);
        resultSet.close();
    }
    // test https://issues.apache.org/jira/browse/IOTDB-1457
    initDataArray = new String[] { "INSERT INTO root.ln.wf011.wt0110(timestamp, temperature) values(250, 10.0)", "INSERT INTO root.ln.wf011.wt0111(timestamp, temperature) values(300, 20.0)", "INSERT INTO root.ln.wf011.wt0112(timestamp, temperature) values(350, 25.0)" };
    for (String initData : initDataArray) {
        writeStatement.execute(initData);
    }
    try {
        session.executeNonQueryStatement(" delete from root.ln.wf011.*");
    } catch (StatementExecutionException | IoTDBConnectionException e) {
        Assert.assertFalse(e instanceof BatchExecutionException);
    }
    // test dictionary encoding
    writeStatement.execute("create timeseries root.ln.wf01.wt02.city WITH DATATYPE=TEXT, ENCODING=DICTIONARY");
    initDataArray = new String[] { "INSERT INTO root.ln.wf01.wt02(timestamp, city) values(250, \"Nanjing\")", "INSERT INTO root.ln.wf01.wt02(timestamp, city) values(300, \"Nanjing\")", "INSERT INTO root.ln.wf01.wt02(timestamp, city) values(350, \"Singapore\")", "INSERT INTO root.ln.wf01.wt02(timestamp, city) values(400, \"Shanghai\")" };
    for (String initData : initDataArray) {
        writeStatement.execute(initData);
    }
    String[] results = new String[] { "Nanjing", "Nanjing", "Singapore", "Shanghai" };
    for (Statement readStatement : readStatements) {
